import io
import os
import runpy
import sys
import unittest
from unittest.mock import patch


def student_file():
    """PythonGrader uses student.py; Udemy coding exercises use exercise.py."""
    for name in ('student.py', 'exercise.py'):
        if os.path.isfile(name):
            return name
    return 'student.py'


class HelloNameTests(unittest.TestCase):
    def run_student(self, name):
        output = io.StringIO()
        with patch('builtins.input', return_value=name):
            with patch('sys.stdout', output):
                runpy.run_path(student_file(), run_name='__main__')
        return output.getvalue().strip()

    def test_chuck(self):
        self.assertEqual(self.run_student('Chuck'), 'Hello Chuck')

    def test_ada(self):
        self.assertEqual(self.run_student('Ada'), 'Hello Ada')
